   private Set<String> registeredComponents = new HashSet<>();

   @Override
   public void beforeCheckEachProject(@NonNull Context context) {
       registeredComponents.clear();
       File manifest = context.getProject().getManifest();
       if (manifest == null || !manifest.exists()) return;

       try {
           Document doc = XmlUtils.parseDocument(manifest, true);
           Element root = doc.getDocumentElement();
           if (root == null || !root.getTagName().equals("manifest")) return;

           String pkg = root.getAttribute("package");
           if (pkg == null || pkg.isEmpty()) {
               pkg = context.getProject().getPackage();
           }
           if (pkg == null) pkg = "";

           Element app = getFirstChild(root, "application");
           if (app == null) return;

           for (Element child = getFirstChild(app); child != null; child = getNextSibling(child)) {
               String tag = child.getTagName();
               if (tag.equals("activity") || tag.equals("service") || tag.equals("provider") || tag.equals("receiver")) {
                   String name = child.getAttributeNS(SdkConstants.ANDROID_URI, "name");
                   if (name != null && !name.isEmpty()) {
                       registeredComponents.add(resolveClassName(pkg, name));
                   }
               }
           }
       } catch (Exception e) {
           // ignore parse errors
       }
   }
   ```
